(() => {
  'use strict';
  const header = document.querySelector('.site-header');
  const progress = document.querySelector('.read-progress span');
  const toTop = document.querySelector('.to-top');
  let ticking = false;
  const update = () => {
    ticking = false;
    const max = document.documentElement.scrollHeight - window.innerHeight;
    const long = max > window.innerHeight * 2.5;
    if (progress) progress.style.transform = 'scaleX(' + (long && max > 0 ? Math.min(1, window.scrollY / max) : 0) + ')';
    toTop?.classList.toggle('visible', window.scrollY > window.innerHeight * 1.5);
  };
  const onScroll = () => {
    header?.classList.toggle('scrolled', window.scrollY > 8);
    if (!ticking) { ticking = true; requestAnimationFrame(update); }
  };
  onScroll();
  window.addEventListener('scroll', onScroll, {passive: true});

  const menu = document.querySelector('.nav-links');
  const menuButton = document.querySelector('.menu-toggle');
  const closeMenu = () => { menu?.classList.remove('open'); menuButton?.setAttribute('aria-expanded', 'false'); menuButton?.setAttribute('aria-label', 'Open navigation'); };
  menuButton?.addEventListener('click', () => {
    const isOpen = menuButton.getAttribute('aria-expanded') === 'true';
    menu.classList.toggle('open', !isOpen);
    menuButton.setAttribute('aria-expanded', String(!isOpen));
    menuButton.setAttribute('aria-label', isOpen ? 'Open navigation' : 'Close navigation');
  });
  menu?.querySelectorAll('a').forEach(a => a.addEventListener('click', closeMenu));
  document.addEventListener('keydown', e => { if (e.key === 'Escape') { closeMenu(); } });
  document.addEventListener('click', e => { if (!header?.contains(e.target)) closeMenu(); });
  window.matchMedia('(min-width: 601px)').addEventListener('change', e => { if (e.matches) closeMenu(); });

  // Content is visible without JavaScript and if IntersectionObserver is unavailable.
  const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if ('IntersectionObserver' in window && !reducedMotion) {
    document.documentElement.classList.add('js');
    const observer = new IntersectionObserver(entries => {
      entries.forEach(entry => { if (entry.isIntersecting) { entry.target.classList.add('visible'); observer.unobserve(entry.target); } });
    }, {threshold: 0.08});
    document.querySelectorAll('.reveal').forEach(el => observer.observe(el));
  }

  const sections = [...document.querySelectorAll('main > section[id]')];
  if ('IntersectionObserver' in window && sections.length) {
    const sectionObserver = new IntersectionObserver(entries => {
      entries.filter(e => e.isIntersecting).forEach(entry => {
        document.querySelectorAll('.nav-links a').forEach(a => {
          const active = a.getAttribute('href') === '#' + entry.target.id;
          if (active) a.setAttribute('aria-current', 'true'); else a.removeAttribute('aria-current');
        });
      });
    }, {rootMargin: '-15% 0px -55% 0px'});
    sections.forEach(section => sectionObserver.observe(section));
  }

  // Case studies: highlight the section the reader is currently in.
  const caseLinks = [...document.querySelectorAll('.case-sidebar a[href^="#"], .rx-case-nav a[href^="#"], .ce-toc a[href^="#"]')];
  const caseSections = caseLinks.map(a => document.getElementById(a.getAttribute('href').slice(1))).filter(Boolean);
  if ('IntersectionObserver' in window && caseSections.length) {
    const caseObserver = new IntersectionObserver(entries => {
      entries.filter(e => e.isIntersecting).forEach(entry => {
        caseLinks.forEach(a => {
          if (a.getAttribute('href') === '#' + entry.target.id) {
            a.setAttribute('aria-current', 'true');
            // On narrow screens the contents bar scrolls sideways: keep the active item visible.
            const bar = a.closest('.case-sidebar, .rx-case-nav, .ce-toc nav');
            if (bar && bar.scrollWidth > bar.clientWidth) bar.scrollTo({left: a.offsetLeft - 20, behavior: reducedMotion ? 'auto' : 'smooth'});
          } else a.removeAttribute('aria-current');
        });
      });
    }, {rootMargin: '-20% 0px -65% 0px'});
    caseSections.forEach(section => caseObserver.observe(section));
  }

  // 404: echo the path that was requested.
  const requested = document.querySelector('[data-request-path]');
  if (requested) requested.textContent = window.location.pathname.replace(/^\/RaghadHanon\.Portfolio\.github\.io/i, '') || '/';

  // A note for the curious who open DevTools.
  if (window.console && !window.__rhGreeted) {
    window.__rhGreeted = true;
    console.log('%cReading the source? We’d get along.', 'font:600 15px Manrope,Arial,sans-serif;color:#b84d2e');
    console.log('%cRaghad Hanon · .NET backend engineer · raghadhanoon2015@gmail.com\nThis site is generated by Python scripts: https://github.com/RaghadHanon/RaghadHanon.Portfolio.github.io', 'font:12px monospace;color:#62645e');
  }

  // Skill map: a tea cup follows a task along the road; each village opens a skill bubble.
  document.querySelectorAll('[data-skillmap]').forEach(map => {
    const pins = [...map.querySelectorAll('.sm-pin')];
    const host = map.querySelector('.sm-panels');
    const stage = map.querySelector('.sm-stage');
    const road = map.querySelector('#sm-road');
    const cup = map.querySelector('.sm-cup');
    const play = map.querySelector('.sm-play');
    const playLabel = map.querySelector('.sm-play-label');
    const status = map.querySelector('.sm-status');
    const segs = [...map.querySelectorAll('.sm-progress i')];
    const bubbles = [...map.querySelectorAll('[data-sm-bubble]')];
    const confetti = map.querySelector('.sm-confetti');
    const stops = pins.filter(p => p.dataset.smStop).sort((a, b) => a.dataset.smStop - b.dataset.smStop);
    const narrow = window.matchMedia('(max-width: 760px)');
    if (!pins.length || !host || !stage) return;
    map.classList.add('sm-ready');
    map.querySelectorAll('[data-sm-js], .sm-next').forEach(el => { el.hidden = false; });

    let total = 0, lengths = null, at = 0, token = 0, raf, timer;
    const measure = () => {
      if (lengths || !road || narrow.matches) return !!lengths;
      try {
        total = road.getTotalLength();
        lengths = stops.map(pin => {
          const x = +pin.dataset.x, y = +pin.dataset.y;
          let best = 0, bestD = Infinity;
          for (let l = 0; l <= total; l += 3) {
            const p = road.getPointAtLength(l), d = (p.x - x) ** 2 + (p.y - y) ** 2;
            if (d < bestD) { bestD = d; best = l; }
          }
          return best;
        });
      } catch (_) { lengths = null; }
      return !!lengths;
    };
    const place = len => {
      const p = road.getPointAtLength(len);
      cup.style.left = (p.x / 1200 * 100) + '%';
      cup.style.top = (p.y / 600 * 100) + '%';
      at = len;
    };
    const tween = (to, my) => new Promise(resolve => {
      if (!measure()) return resolve();
      const from = at, ms = reducedMotion ? 0 : Math.min(1500, 260 + Math.abs(to - from) * 2.2);
      if (!ms || Math.abs(to - from) < 1) { place(to); return resolve(); }
      const start = performance.now();
      const step = now => {
        if (my !== token) return resolve();
        const t = Math.min(1, (now - start) / ms), e = t < .5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
        place(from + (to - from) * e);
        if (t < 1) raf = requestAnimationFrame(step); else resolve();
      };
      raf = requestAnimationFrame(step);
    });
    const wait = ms => new Promise(resolve => { timer = setTimeout(resolve, ms); });

    // Bubbles sit in the open middle of the map: below top-row villages, above bottom-row ones.
    const hideBubbles = () => bubbles.forEach(b => { b.hidden = true; });
    const showBubble = pin => {
      hideBubbles();
      if (narrow.matches) return;
      const bubble = bubbles.find(b => b.dataset.smBubble === pin.dataset.smKey);
      if (!bubble) return;
      const W = stage.clientWidth, H = stage.clientHeight, s = W / 1200;
      const x = +pin.dataset.x * s, y = +pin.dataset.y * s;
      const above = +pin.dataset.y > 300;
      bubble.classList.toggle('is-above', above);
      bubble.hidden = false;
      const bw = bubble.offsetWidth, margin = 14;
      const left = Math.max(bw / 2 + margin, Math.min(W - bw / 2 - margin, x));
      bubble.style.left = left + 'px';
      bubble.style.top = (above ? Math.max(y - 86 * s, bubble.offsetHeight + margin) : Math.min(y + 62 * s, H - bubble.offsetHeight - margin)) + 'px';
      bubble.style.setProperty('--ox', Math.max(22, Math.min(bw - 22, x - left + bw / 2)) + 'px');
      bubble.style.animation = 'none'; void bubble.offsetWidth; bubble.style.animation = '';
    };
    const dock = pin => {
      if (narrow.matches) pin.closest('li').append(host);
      else if (stage.nextElementSibling !== host) stage.after(host);
    };
    const select = (pin, bubble = true) => {
      pins.forEach(p => {
        const on = p === pin;
        p.setAttribute('aria-pressed', String(on));
        const panel = document.getElementById(p.getAttribute('aria-controls'));
        if (panel) panel.hidden = !on;
      });
      dock(pin);
      if (bubble) showBubble(pin); else hideBubbles();
    };
    const progress = n => segs.forEach((seg, i) => seg.classList.toggle('on', i < n));
    const markDone = n => stops.forEach((pin, i) => pin.classList.toggle('is-done', i < n));
    const nameOf = pin => pin.querySelector('.sm-name')?.firstChild?.textContent.trim() || '';
    const setPlaying = on => {
      map.classList.toggle('is-playing', on);
      play?.setAttribute('aria-pressed', String(on));
      if (playLabel) playLabel.textContent = on ? 'Stop' : (map.classList.contains('is-done') ? 'Play again' : 'Start a task');
    };
    const stop = message => {
      token++; cancelAnimationFrame(raf); clearTimeout(timer);
      setPlaying(false);
      if (message && status) status.textContent = message;
    };
    const celebrate = () => {
      if (!confetti || reducedMotion || narrow.matches) return;
      confetti.innerHTML = '';
      const colors = ['#c0532f', '#f2c879', '#5f8f98', '#7f9c72', '#fbf6ea'];
      for (let i = 0; i < 34; i++) {
        const c = document.createElement('i');
        const a = Math.random() * Math.PI * 1.2 - Math.PI * 1.1, r = 60 + Math.random() * 110;
        c.style.cssText = `--cx:${55 / 1200 * 100}%;--cy:${390 / 600 * 100}%;--tx:${Math.cos(a) * r + 30}px;--ty:${Math.sin(a) * r}px;--r:${Math.random() * 720 - 360}deg;--d:${Math.random() * .15}s;background:${colors[i % colors.length]}`;
        confetti.append(c);
      }
      setTimeout(() => { confetti.innerHTML = ''; }, 1700);
    };
    const run = async () => {
      const my = ++token;
      map.classList.remove('is-done');
      setPlaying(true);
      progress(0); markDone(0); hideBubbles();
      if (measure()) { cup.classList.add('on'); place(0); }
      for (let i = 0; i < stops.length; i++) {
        if (status) status.textContent = 'Travelling to ' + nameOf(stops[i]) + '…';
        if (lengths) await tween(lengths[i], my);
        if (my !== token) return;
        select(stops[i]);
        progress(i + 1);
        if (narrow.matches) stops[i].scrollIntoView({block: 'nearest', behavior: reducedMotion ? 'auto' : 'smooth'});
        if (status) status.textContent = 'Stop ' + (i + 1) + ' of ' + stops.length + ': ' + nameOf(stops[i]);
        await wait(reducedMotion ? 2600 : 2400);
        if (my !== token) return;
        markDone(i + 1);
      }
      hideBubbles();
      if (lengths) await tween(total, my);
      if (my !== token) return;
      map.classList.add('is-done');
      stop('Quest complete: shipped to production.');
      celebrate();
    };
    play?.addEventListener('click', () => {
      if (play.getAttribute('aria-pressed') === 'true') stop('Paused. Open any village to read more.');
      else run();
    });
    const go = pin => {
      stop();
      select(pin);
      const i = stops.indexOf(pin);
      if (status) status.textContent = i >= 0 ? 'Stop ' + (i + 1) + ' of ' + stops.length + ': ' + nameOf(pin) : nameOf(pin);
      if (i >= 0 && measure()) { cup.classList.add('on'); tween(lengths[i], token); }
    };
    pins.forEach(pin => pin.addEventListener('click', () => go(pin)));
    map.querySelectorAll('[data-sm-go]').forEach(button => button.addEventListener('click', () => {
      const pin = pins.find(p => p.dataset.smKey === button.dataset.smGo);
      if (pin) { go(pin); if (narrow.matches) pin.scrollIntoView({block: 'nearest'}); }
    }));
    map.addEventListener('keydown', e => { if (e.key === 'Escape') hideBubbles(); });
    let resizeTimer;
    window.addEventListener('resize', () => {
      clearTimeout(resizeTimer);
      resizeTimer = setTimeout(() => {
        const current = pins.find(p => p.getAttribute('aria-pressed') === 'true');
        if (current && bubbles.some(b => !b.hidden)) showBubble(current);
      }, 120);
    });
    narrow.addEventListener('change', () => {
      stop();
      const current = pins.find(p => p.getAttribute('aria-pressed') === 'true');
      if (current) dock(current);
      hideBubbles();
      if (!narrow.matches && measure()) { cup.classList.add('on'); place(at); }
    });
    select(stops[0] || pins[0], false);
    if (measure()) place(0);
  });

  // "Hire me as an API": endpoints behave as tabs; all responses are in the HTML without JS.
  document.querySelectorAll('[data-api-console]').forEach(consoleEl => {
    const calls = [...consoleEl.querySelectorAll('.api-endpoint')];
    const output = consoleEl.querySelector('.api-output');
    let timer;
    const select = (call, animate) => {
      calls.forEach(c => {
        const on = c === call;
        c.setAttribute('aria-selected', String(on));
        c.tabIndex = on ? 0 : -1;
        const panel = document.getElementById(c.getAttribute('aria-controls'));
        if (panel) panel.hidden = !on;
      });
      if (animate && output && !reducedMotion) {
        clearTimeout(timer); output.classList.add('is-sending');
        timer = setTimeout(() => output.classList.remove('is-sending'), 280);
      }
    };
    calls.forEach((call, i) => {
      call.addEventListener('click', () => select(call, true));
      call.addEventListener('keydown', e => {
        let n;
        if (e.key === 'ArrowDown' || e.key === 'ArrowRight') n = (i + 1) % calls.length;
        if (e.key === 'ArrowUp' || e.key === 'ArrowLeft') n = (i - 1 + calls.length) % calls.length;
        if (e.key === 'Home') n = 0;
        if (e.key === 'End') n = calls.length - 1;
        if (n !== undefined) { e.preventDefault(); select(calls[n], true); calls[n].focus(); }
      });
    });
    if (calls.length) select(calls[0], false);
  });

  const tabs = [...document.querySelectorAll('.engineering-explorer [role="tab"]')];
  const visibleTabs = () => tabs.filter(tab => !tab.hidden);
  const activateTab = tab => {
    tabs.forEach(t => {
      const selected = t === tab;
      t.setAttribute('aria-selected', String(selected));
      t.tabIndex = selected ? 0 : -1;
      const panel = document.getElementById(t.getAttribute('aria-controls'));
      if (panel) panel.hidden = !selected;
    });
  };
  tabs.forEach(tab => {
    tab.addEventListener('click', () => activateTab(tab));
    tab.addEventListener('keydown', e => {
      const available = visibleTabs();
      const index = available.indexOf(tab);
      let next;
      if (e.key === 'ArrowDown' || e.key === 'ArrowRight') next = (index + 1) % available.length;
      if (e.key === 'ArrowUp' || e.key === 'ArrowLeft') next = (index - 1 + available.length) % available.length;
      if (e.key === 'Home') next = 0;
      if (e.key === 'End') next = available.length - 1;
      if (next !== undefined && available[next]) {
        e.preventDefault(); activateTab(available[next]); available[next].focus();
        available[next].scrollIntoView({block: 'nearest', inline: 'nearest'});
      }
    });
  });
  const filters = [...document.querySelectorAll('[data-story-filter]')];
  filters.forEach(filter => {
    filter.addEventListener('click', () => {
      const category = filter.dataset.storyFilter;
      filters.forEach(button => button.setAttribute('aria-pressed', String(button === filter)));
      tabs.forEach(tab => { tab.hidden = category !== 'All' && tab.dataset.storyCategory !== category; });
      const available = visibleTabs();
      if (available.length) activateTab(available[0]);
      const count = document.querySelector('.story-count');
      if (count) count.textContent = available.length + (available.length === 1 ? ' decision' : ' decisions') + ' / ' + (category === 'All' ? 'actual project code' : category);
      const list = document.querySelector('.engineering-explorer .engine-tabs');
      if (list) { list.scrollTop = 0; list.scrollLeft = 0; }
    });
  });
  // Progressive enhancement: all source examples are available in the HTML without JS.
  if (tabs.length) {
    const controls = document.querySelector('.engine-controls');
    if (controls) controls.hidden = false;
    activateTab(tabs[0]);
  }

  document.querySelectorAll('[data-screen-explorer]').forEach(explorer => {
    const choices = [...explorer.querySelectorAll('[data-screen-choice]')];
    const panels = [...explorer.querySelectorAll('.screen-panel')];
    const selectScreen = choice => {
      choices.forEach(button => button.setAttribute('aria-pressed', String(button === choice)));
      panels.forEach(panel => { panel.hidden = panel.id !== choice.dataset.screenChoice; });
    };
    choices.forEach(choice => choice.addEventListener('click', () => selectScreen(choice)));
    if (choices.length) selectScreen(choices[0]);
  });

  const videos = [...document.querySelectorAll('video')];
  videos.forEach(video => {
    video.addEventListener('play', () => {
      videos.forEach(other => { if (other !== video) other.pause(); });
      video.closest('.video-frame')?.classList.add('is-playing');
    });
    const stop = () => video.closest('.video-frame')?.classList.remove('is-playing');
    video.addEventListener('pause', stop);
    video.addEventListener('ended', stop);
  });

  let toastTimer;
  const toast = document.querySelector('.toast');
  const announce = message => {
    if (!toast) return;
    toast.textContent = message; toast.classList.add('visible');
    clearTimeout(toastTimer); toastTimer = setTimeout(() => toast.classList.remove('visible'), 3500);
  };
  document.querySelectorAll('[data-copy-email]').forEach(button => {
    button.addEventListener('click', async () => {
      const email = button.dataset.copyEmail;
      try {
        if (navigator.clipboard && window.isSecureContext) await navigator.clipboard.writeText(email);
        else {
          const field = document.createElement('textarea');
          field.value = email; field.style.position = 'fixed'; field.style.opacity = '0';
          document.body.appendChild(field); field.select();
          const copied = document.execCommand('copy'); field.remove();
          if (!copied) throw new Error('Copy unavailable');
        }
        announce('Email copied. Let’s make something good.');
      } catch (_) { announce('Email: ' + email); }
    });
  });

  const lightbox = document.querySelector('.lightbox');
  const lightboxImage = lightbox?.querySelector('img');
  const caption = lightbox?.querySelector('p');
  document.querySelectorAll('[data-zoom]').forEach(button => {
    button.addEventListener('click', () => {
      if (!lightbox || typeof lightbox.showModal !== 'function') { window.open(button.dataset.zoom, '_blank', 'noopener'); return; }
      lightboxImage.src = button.dataset.zoom;
      lightboxImage.alt = button.querySelector('img')?.alt || 'Project screenshot';
      caption.textContent = button.dataset.caption || lightboxImage.alt;
      lightbox.showModal(); document.body.classList.add('lightbox-open');
    });
  });
  lightbox?.querySelector('.close-lightbox')?.addEventListener('click', () => lightbox.close());
  lightbox?.addEventListener('close', () => { document.body.classList.remove('lightbox-open'); });
  lightbox?.addEventListener('click', e => { if (e.target === lightbox) lightbox.close(); });
})();
